ЗагСупа.Вставить("apikey", ТокенСупа);
ЗагСупа.Вставить("Authorization", "Bearer " + ТокенСупа);
ЗагСупа.Вставить("Content-Type", "application/json");
ЗагСупа.Вставить("Accept", "application/json");

Результат = "=== Миграция Git → Supabase ===" + Символы.ПС;
Всего = 0;
Успех = 0;
Ошибок = 0;
ДеревоПолучено = Ложь;
Файлы = Новый Массив;

// --- Шаг 1: Получаем дерево файлов ---
Попытка
    ПутьДерева = "/repos/" + Репозиторий + "/git/trees/" + Ветка + ":" + КаталогЗнаний + "?recursive=1";
    ЗапросДерева = Новый HTTPЗапрос(ПутьДерева, ЗагГит);
    ОтветДерева = Гит.Получить(ЗапросДерева);

    Если ОтветДерева.КодСостояния = 200 Тогда
        Чтение = Новый ЧтениеJSON;
        Чтение.УстановитьСтроку(ОтветДерева.ПолучитьТелоКакСтроку());
        Дерево = ПрочитатьJSON(Чтение, Ложь);
        Чтение.Закрыть();

        Для Каждого Эл Из Дерево.tree Цикл
            Если Эл.type = "blob" И НРег(Прав(Эл.path, 5)) = ".json" Тогда
                Файлы.Добавить(Эл.path);
            КонецЕсли;
        КонецЦикла;

        Всего = Файлы.Количество();
        Результат = Результат + "Найдено JSON-файлов: " + Строка(Всего) + Символы.ПС;
        ДеревоПолучено = Истина;
    Иначе
        Результат = Результат + "ОШИБКА дерева: HTTP " + Строка(ОтветДерева.КодСостояния) + Символы.ПС;
    КонецЕсли;
Исключение
    Результат = Результат + "ОШИБКА дерева: " + ОписаниеОшибки() + Символы.ПС;
КонецПопытки;

// --- Шаг 2: Обходим файлы, вставляем пачками ---
Если ДеревоПолучено И Всего > 0 Тогда
    Буфер = Новый Массив;
    РазмерПачки = 50;
    Сч = 0;

    Для Каждого ПутьФайла Из Файлы Цикл
        Сч = Сч + 1;

        Попытка
            ПутьКонтента = "/repos/" + Репозиторий + "/contents/" + ПутьФайла;
            ЗапросФайла = Новый HTTPЗапрос(ПутьКонтента, ЗагГитRaw);
            ОтветФайла = Гит.Получить(ЗапросФайла);

            Если ОтветФайла.КодСостояния = 200 Тогда
                Ч = Новый ЧтениеJSON;
                Ч.УстановитьСтроку(ОтветФайла.ПолучитьТелоКакСтроку());
                Запись = ПрочитатьJSON(Ч, Ложь);
                Ч.Закрыть();

                ВремяМетка = "";
                Если Запись.Свойство("timestamp") Тогда
                    ВремяМетка = Запись.timestamp;
                КонецЕсли;
                Если НЕ ЗначениеЗаполнено(ВремяМетка) Тогда
                    ВремяМетка = Формат(ТекущаяДата(), "ДФ=yyyy-MM-ddTHH:mm:ssZ");
                КонецЕсли;

                Зап = Новый Структура;
                Зап.Вставить("fingerprint", ?(Запись.Свойство("fingerprint"), Запись.fingerprint, ""));
                Зап.Вставить("task",        ?(Запись.Свойство("task"),        Запись.task, ""));
                Зап.Вставить("code",        ?(Запись.Свойство("code"),        Запись.code, ""));
                Зап.Вставить("lang",        ?(Запись.Свойство("lang"),        Запись.lang, ""));
                Зап.Вставить("result",      ?(Запись.Свойство("result"),      Запись.result, ""));
                Зап.Вставить("success",     ?(Запись.Свойство("success"),     Запись.success, Ложь));
                Зап.Вставить("type",        ?(Запись.Свойство("type"),        Запись.type, ""));
                Зап.Вставить("timestamp",   ВремяМетка);

                Буфер.Добавить(Зап);
            Иначе
                Ошибок = Ошибок + 1;
            КонецЕсли;
        Исключение
            Ошибок = Ошибок + 1;
        КонецПопытки;

        // Отправляем пачку
        Если Буфер.Количество() >= РазмерПачки ИЛИ (Сч = Всего И Буфер.Количество() > 0) Тогда
            Попытка
                ЗапJSON = Новый ЗаписьJSON;
                ЗапJSON.УстановитьСтроку();
                ЗапJSON.ЗаписатьНачалоМассива();
                Для Каждого З Из Буфер Цикл
                    ЗапJSON.ЗаписатьНачалоОбъекта();
                    ЗапJSON.ЗаписатьИмяСвойства("fingerprint"); ЗапJSON.ЗаписатьЗначение(З.fingerprint);
                    ЗапJSON.ЗаписатьИмяСвойства("task");        ЗапJSON.ЗаписатьЗначение(З.task);
                    ЗапJSON.ЗаписатьИмяСвойства("code");        ЗапJSON.ЗаписатьЗначение(З.code);
                    ЗапJSON.ЗаписатьИмяСвойства("lang");        ЗапJSON.ЗаписатьЗначение(З.lang);
                    ЗапJSON.ЗаписатьИмяСвойства("result");      ЗапJSON.ЗаписатьЗначение(З.result);
                    ЗапJSON.ЗаписатьИмяСвойства("success");     ЗапJSON.ЗаписатьЗначение(З.success);
                    ЗапJSON.ЗаписатьИмяСвойства("type");        ЗапJSON.ЗаписатьЗначение(З.type);
                    ЗапJSON.ЗаписатьИмяСвойства("timestamp");   ЗапJSON.ЗаписатьЗначение(З.timestamp);
                    ЗапJSON.ЗаписатьКонецОбъекта();
                КонецЦикла;
                ЗапJSON.ЗаписатьКонецМассива();
                ТелоПачки = ЗапJSON.Закрыть();

                ЗапросВставки = Новый HTTPЗапрос("/rest/v1/knowledge", ЗагСупа);
                ЗапросВставки.УстановитьТелоИзСтроки(ТелоПачки, КодировкаТекста.UTF8, ИспользованиеByteOrderMark.НеИспользовать);
                ОтветВставки = Супа.ОтправитьДляОбработки(ЗапросВставки);

                Если ОтветВставки.КодСостояния >= 200 И ОтветВставки.КодСостояния < 300 Тогда
                    Успех = Успех + Буфер.Количество();
                Иначе
                    Ошибок = Ошибок + Буфер.Количество();
                КонецЕсли;
            Исключение
                Ошибок = Ошибок + Буфер.Количество();
            КонецПопытки;
            Буфер.Очистить();
        КонецЕсли;

    КонецЦикла;

    Результат = Результат + "Обработано: " + Строка(Сч) + Символы.ПС;
КонецЕсли;

Результат = Результат
    + "Вставлено: " + Строка(Успех) + Символы.ПС
    + "Ошибок: " + Строка(Ошибок) + Символы.ПС
    + "=== Готово ===";
